<script setup lang="ts">
const props=defineProps<{accountId:string;canManage:boolean}>();const {api,path,run,loading,errors}=useAuthorizationWorkspace(()=>props.accountId)
const policies=ref<any[]>([]),selected=ref<any>(null),view=ref('policies'),decision=ref<any>(null),timezones=ref<string[]>([]),defaultTimezone=ref('UTC'),editingId=ref<string|null>(null),deleteDialog=ref(false)
const makeEvent=()=>({event_id:null,subject:'*',resource:'*',action:'read',location:null as any,radius_km:1,time_mode:'wildcard',time_start:null,time_end:null})
const form=reactive<any>({name:'',effect:'ALLOW',timezone:'',events:[makeEvent()]});const evaluate=reactive<any>({subject:'',resource:'',action:'',time:'',location:null})
async function load(){const [p,z]:any[]=await Promise.all([run('policies',()=>api(path('abac/policies'))),run('timezones',()=>api(path('abac/timezones')))]);policies.value=p||[];timezones.value=z?.timezones||[];defaultTimezone.value=z?.default||'UTC';if(selected.value)selected.value=policies.value.find(x=>x.policy_id===selected.value.policy_id)||null}
function choose(policy:any){selected.value=policy}
function resetForm(){editingId.value=null;Object.assign(form,{name:'',effect:'ALLOW',timezone:'',events:[makeEvent()]})}
function editPolicy(policy:any){editingId.value=policy.policy_id;Object.assign(form,{name:policy.name,effect:policy.effect,timezone:policy.timezone,events:policy.events.map((e:any)=>({event_id:e.event_id,subject:e.subject.value,resource:e.resource.value,action:e.action.value,location:e.location.center?{...e.location.center}:null,radius_km:e.location.radius_km,time_mode:e.time.mode,time_start:e.time.start,time_end:e.time.end}))});view.value='editor'}
async function upgrade(policy:any){await run(`upgrade-${policy.policy_id}`,()=>api(path(`abac/policies/${policy.policy_id}/upgrade-matcher`),{method:'POST'}));await load()}
async function save(){const events=form.events.map((e:any)=>({event_id:e.event_id||undefined,subject:e.subject,resource:e.resource,action:e.action,location:e.location?{...e.location,radius_km:e.radius_km}:null,time_mode:e.time_mode,time_start:e.time_mode==='wildcard'?null:e.time_start,time_end:e.time_mode==='wildcard'?null:e.time_end}));const body={name:form.name,effect:form.effect,timezone:form.timezone||undefined,events};const saved:any=editingId.value?await run('save-policy',()=>api(path(`abac/policies/${editingId.value}`),{method:'PUT',body})):await run('create-policy',()=>api(path('abac/policies'),{method:'POST',body}));if(saved){const id=editingId.value||saved.policy_id;resetForm();await load();selected.value=policies.value.find(p=>p.policy_id===id)||null;view.value='policies'}}
async function remove(){if(!selected.value)return;await run('delete-policy',()=>api(path(`abac/policies/${selected.value.policy_id}`),{method:'DELETE'}));deleteDialog.value=false;selected.value=null;await load()}
async function test(){decision.value=null;decision.value=await run('evaluate',()=>api(path('abac/evaluate'),{method:'POST',body:{...evaluate,time:evaluate.time||null}}))}
watch(()=>props.accountId,()=>{policies.value=[];selected.value=null;decision.value=null;deleteDialog.value=false;resetForm();load()},{immediate:true})
</script>
<template><div class="pa-5 pa-md-7"><v-alert v-for="(e,k) in errors" v-show="e" :key="k" type="error" variant="tonal" class="mb-3">{{e}}</v-alert><div><h2 class="text-h5">Attribute-based policies</h2><p class="text-medium-emphasis">Anchored glob matching, policy-local timezones, and synchronized geographic conditions.</p></div><v-tabs v-model="view"><v-tab value="policies">Policies</v-tab><v-tab value="editor">Policy editor</v-tab><v-tab value="evaluator">Evaluator</v-tab></v-tabs><v-window v-model="view">
<v-window-item value="policies"><v-row class="mt-3"><v-col cols="12" md="5"><v-list lines="three"><v-list-item v-for="p in policies" :key="p.policy_id" :active="selected?.policy_id===p.policy_id" :title="p.name" :subtitle="`${p.effect} · ${p.matcher_version} · ${p.timezone} · ${p.events.length} events`" @click="choose(p)"><template #prepend><v-icon :color="p.effect==='ALLOW'?'success':'error'" :icon="p.effect==='ALLOW'?'mdi-check-circle-outline':'mdi-cancel'"/></template></v-list-item></v-list><v-alert v-if="!policies.length&&!loading.policies" type="info" variant="tonal">No policies.</v-alert></v-col><v-col cols="12" md="7"><v-alert v-if="!selected" type="info" variant="tonal">Select a policy for complete details.</v-alert><v-card v-else variant="outlined"><v-card-title>{{selected.name}}<v-spacer/><v-btn v-if="canManage" icon="mdi-pencil-outline" variant="text" @click="editPolicy(selected)"/><v-btn v-if="canManage" icon="mdi-delete-outline" color="error" variant="text" @click="deleteDialog=true"/></v-card-title><v-card-subtitle class="xolo-mono">{{selected.policy_id}}</v-card-subtitle><v-card-text><v-list density="compact"><v-list-item title="Matcher" :subtitle="selected.matcher_version"/><v-list-item title="Timezone" :subtitle="selected.timezone"/><v-list-item title="Created" :subtitle="new Date(selected.created_at).toLocaleString()"/><v-list-item title="Updated" :subtitle="new Date(selected.updated_at).toLocaleString()"/></v-list><v-card v-for="(e,i) in selected.events" :key="e.event_id" variant="tonal" class="mb-3"><v-card-title class="text-subtitle-1">Event {{i+1}} · {{e.event_id}}</v-card-title><v-card-text><div>{{e.subject.value}} → {{e.resource.value}} · {{e.action.value}}</div><div>Time: {{e.time.mode}} {{e.time.start||''}} {{e.time.end||''}}</div><template v-if="e.location.center"><div>Coordinates: {{e.location.center.lat}}, {{e.location.center.lng}} · radius {{e.location.radius_km}} km</div><ClientOnly><AuthorizationPolicyMap :lat="e.location.center.lat" :lng="e.location.center.lng" :radius-km="e.location.radius_km" :popup="`${selected.name} · ${e.event_id}`"/></ClientOnly></template></v-card-text></v-card><v-btn v-if="canManage&&selected.matcher_version==='legacy_v1'" variant="tonal" @click="upgrade(selected)">Upgrade matcher</v-btn></v-card-text></v-card></v-col></v-row></v-window-item>
<v-window-item value="editor"><v-card v-if="canManage" variant="outlined" class="mt-4"><v-card-title>{{editingId?'Edit policy':'Create policy'}}</v-card-title><v-card-text><v-row><v-col cols="12" md="6"><v-text-field v-model="form.name" label="Policy name"/></v-col><v-col cols="6" md="3"><v-select v-model="form.effect" :items="['ALLOW','DENY']" label="Effect"/></v-col><v-col cols="6" md="3"><v-autocomplete v-model="form.timezone" :items="timezones" clearable label="IANA timezone" :hint="`Account default: ${defaultTimezone}`" persistent-hint/></v-col></v-row><v-card v-for="(e,i) in form.events" :key="e.event_id||i" variant="tonal" class="mb-4"><v-card-title>Event {{i+1}}<span v-if="e.event_id" class="text-caption xolo-mono ml-2">{{e.event_id}}</span><v-spacer/><v-btn v-if="form.events.length>1" icon="mdi-close" variant="text" @click="form.events.splice(i,1)"/></v-card-title><v-card-text><v-row><v-col cols="12" md="4"><v-text-field v-model="e.subject" label="Subject pattern"/></v-col><v-col cols="12" md="4"><v-text-field v-model="e.resource" label="Resource pattern"/></v-col><v-col cols="12" md="4"><v-text-field v-model="e.action" label="Action pattern"/></v-col><v-col cols="12" md="4"><v-select v-model="e.time_mode" :items="['wildcard','datetime','time_of_day','date']" label="Time mode"/></v-col><v-col v-if="e.time_mode!=='wildcard'" cols="12" md="4"><v-text-field v-model="e.time_start" label="Start"/></v-col><v-col v-if="e.time_mode!=='wildcard'" cols="12" md="4"><v-text-field v-model="e.time_end" label="End"/></v-col></v-row><v-switch :model-value="!!e.location" label="Restrict by location" @update:model-value="v=>e.location=v?{lat:19.4326,lng:-99.1332}:null"/><template v-if="e.location"><v-row><v-col><v-number-input v-model="e.location.lat" label="Latitude"/></v-col><v-col><v-number-input v-model="e.location.lng" label="Longitude"/></v-col></v-row><v-slider v-model="e.radius_km" :min="0.1" :max="5" :step="0.1" thumb-label label="Radius km"/><ClientOnly><AuthorizationPolicyMap :lat="e.location.lat" :lng="e.location.lng" :radius-km="e.radius_km" :popup="`Event ${i+1}`" @change="p=>e.location={...p}"/></ClientOnly></template></v-card-text></v-card><v-btn variant="tonal" prepend-icon="mdi-plus" @click="form.events.push(makeEvent())">Add event</v-btn></v-card-text><v-card-actions><v-btn v-if="editingId" @click="resetForm">Cancel edit</v-btn><v-spacer/><v-btn color="primary" :loading="loading['save-policy']||loading['create-policy']" :disabled="!form.name" @click="save">{{editingId?'Save changes':'Create policy'}}</v-btn></v-card-actions></v-card></v-window-item>
<v-window-item value="evaluator"><v-card variant="outlined" class="mt-4"><v-card-text><v-row><v-col cols="12" md="4"><v-text-field v-model="evaluate.subject" label="Subject"/></v-col><v-col cols="12" md="4"><v-text-field v-model="evaluate.resource" label="Resource"/></v-col><v-col cols="12" md="4"><v-text-field v-model="evaluate.action" label="Action"/></v-col><v-col cols="12"><v-text-field v-model="evaluate.time" label="Timezone-aware ISO datetime" placeholder="2026-10-13T12:00:00-06:00"/></v-col></v-row><v-switch :model-value="!!evaluate.location" label="Include request location" @update:model-value="v=>evaluate.location=v?{lat:19.4326,lng:-99.1332}:null"/><ClientOnly v-if="evaluate.location"><AuthorizationPolicyMap :lat="evaluate.location.lat" :lng="evaluate.location.lng" :radius-km="0.1" @change="p=>evaluate.location=p"/></ClientOnly><v-btn color="primary" class="mt-3" @click="test">Evaluate</v-btn><v-alert v-if="decision" :type="decision.allowed?'success':'error'" variant="tonal" class="mt-4"><strong>{{decision.allowed?'Allowed':'Denied'}}</strong> — {{decision.reason}}<div>Matched policies: {{decision.matched_policy_ids?.join(', ')||'none'}}</div><div>Matched events: {{decision.matched_event_ids?.join(', ')||'none'}}</div><div v-for="w in decision.warnings" :key="w" class="text-caption text-warning">{{w}}</div></v-alert></v-card-text></v-card></v-window-item></v-window><v-dialog v-model="deleteDialog" max-width="520"><v-card title="Delete ABAC policy?"><v-card-text>This permanently deletes {{selected?.name}} and its {{selected?.events.length||0}} events.</v-card-text><v-card-actions><v-spacer/><v-btn @click="deleteDialog=false">Cancel</v-btn><v-btn color="error" :loading="loading['delete-policy']" @click="remove">Delete</v-btn></v-card-actions></v-card></v-dialog></div></template>
